INSERT INTO purpose VALUES('storage-values','chunk::CHUNK_DOMAIN','constant','Names the domain every chunk image opens with, inside the hashed preimage, so one backing object can serve both storage planes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','chunk::ChunkStore','trait','Names the verified backing store for value-plane chunks, first-write-wins, a sibling of the record plane''s node store rather than a use of it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','chunk::FramedChunk','struct','Holds an owned chunk image this crate framed, with its digest, the only way a chunk comes into existence.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','chunk::InMemoryChunkStore','struct','Holds a deterministic in-memory ChunkStore, the deterministic memory implementation of verified chunk storage.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','chunk::StoredChunkRef','struct','Holds a framed chunk image and the digest it is claimed to hash to, unverified, the claim a verification checks against.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','chunk::VerifiedChunk','struct','Holds a chunk image whose digest, frame, records and token count have been checked, obtainable only by verification or by framing a body.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','chunk::frame_chunk','function','Frames a token body into a chunk image and hashes it, the only way a chunk comes into existence so the frame cannot drift from the verifier.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','chunk::verify_chunk_image','function','Checks a claimed chunk: its digest, its frame, its records and their count, the one verification both store halves run.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','closure::ValueClosure','struct','Holds the chunks a reader of a value loads, a nonempty set of authenticated chunk identities, the closure a manifest''s closure checks.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','closure::cam_closure','function','Walks the chunks a dereference of a pointer loads under a classification, so a reader that holds the pointer and no manifest reads where the value resides.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','commit::RESIDUE_DOMAIN','constant','Names the domain every residue preimage opens with, so a residue is a function of a subtree''s own content, not how its descendants were cut.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','commit::cam_commit','function','Commits a value into a store as a chunk DAG and names it, the value plane''s write path, a deterministic function of the value and the profile.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','deref::cam_deref','function','Fetches, verifies and decodes the value a pointer addresses, the value plane''s read path and the portability a content pointer claims.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','error::ChunkFrameField','enum','Names the part of a chunk frame a refusal names, in frame order.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','error::EmissionFault','enum','Names the way a value''s emission broke the one-balanced-value shape a sink requires.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','error::ManifestField','enum','Names the field of a manifest image a refusal names, in image order.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','error::ProfileField','enum','Names the field of a value profile a reader''s expectation can differ in, in manifest image order.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','error::ValueError','enum','Names every way the value plane refuses an input: a missing or mismatched chunk, a malformed frame or emission, a truncated or trailing stream, an alias seam, a spent decode budget, an incompatible profile, or an arithmetic overflow.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','error::ValueQuantity','enum','Names the quantity whose checked arithmetic overflowed.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','flat::decode_flat','function','Decodes one value from its flat form, refusing anything after it, the read half of the flat form.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','flat::encode_flat','function','Encodes one value as its flat form, the value''s canonical bytes without a store, equal to the single chunk''s body for a value that fits one chunk.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','index_base::ChildIndexBase','enum','Names how a child reference names its target inside a chunk body, absolute or chunk-local, bound into the profile so two deployments that disagree refuse each other.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','locality::LocalityMeasurement','struct','Holds one edit''s observed locality: the chunks only the edited value''s closure holds and the chunks the two share.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','locality::expected_chunk_bound','function','Computes the expected number of chunks an edit at a depth affects under a profile, the number a measured mean is read against.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','locality::measure_edit','function','Measures one edit: the chunks reachable from the edited root and not from the original, and the chunks reachable from both.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::BoundaryClassification','enum','Names which constructor exits are boundary candidates, splitting constructors into alias and boundary types.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::BoundaryTags','struct','Holds a set of constructor tags, the boundaries of a tagged classification, one bit per tag.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::CodecIdentity','struct','Holds the canonical token codec a value was encoded through, its stable identifier and layout version.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::ConstructorClass','enum','Names what a constructor is to the chunk DAG, a boundary or an alias.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::DigestFamily','enum','Names the digest family the addresses are taken in.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::MANIFEST_DIGEST_LEN','constant','Names the byte length of a manifest digest, one BLAKE3 output.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::MANIFEST_DOMAIN','constant','Names the domain every manifest image opens with, inside the hashed preimage, so a manifest identity and a chunk digest never hash the same preimage.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::ManifestDigest','struct','Holds the BLAKE3 identity of one manifest image, deliberately not a chunk digest and no conversion offered in either direction.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::ValueManifest','struct','Holds the identity of one committed value: its profile, its root, and the records a reader of the root delivers, the context a content pointer is only meaningful under.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','manifest::ValueProfile','struct','Holds every constant two deployments must agree on to share storage, so two deployments that disagree hold unequal profiles and refuse each other.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','ptr::CHUNK_DIGEST_LEN','constant','Names the byte length of a chunk digest, one BLAKE3 output.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','ptr::ChunkDigest','struct','Holds the BLAKE3 identity of one framed chunk image, deliberately not the record plane''s node identity and no conversion offered in either direction.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','ptr::ContentPtr','struct','Holds a content pointer, a chunk digest and a token offset inside that chunk, the value plane''s whole address vocabulary, stable and portable and independent of any process.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','ptr::TokenOffset','struct','Names a token index inside one chunk''s body, within the chunk never within the whole value, so a pointer stays stable when an unrelated part of the value changes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','reader::TokenReader','struct','Holds a cursor over a value''s token stream that splices child chunks in place and charges every step to one decode budget, so a decoder sees one stream and cannot tell where the seams were.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','tokens::CanonicalValue','trait','Names a value that can be written to, and read back from, the canonical token stream, the codec law that makes a content pointer name a value.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','tokens::ConstructorTag','struct','Holds one constructor tag in a canonical token stream, so a tag cannot be confused with a canonical word or a payload byte at the framing boundary.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','tokens::TokenKind','enum','Names the kinds of token record a body holds: a constructor opens, a word, a byte payload, a child reference, or a close.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','tokens::TokenSink','trait','Names the receiver of one value''s canonical token stream, the common emission boundary for flat and chunked values, refusing an emission that is not exactly one balanced value.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::CanonicalWord','struct','Names one canonical sixty-four-bit payload word, the only integer width the token framing admits.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ChunkBound','struct','Names an expected number of affected chunks, as the locality bound states it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ChunkCount','struct','Names a number of distinct chunks a store holds or an edit added.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ChunkFormatVersion','struct','Names the layout version of a chunk image''s frame.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ChunkImage','struct','Holds a framed chunk image: the domain, the frame header, then the body.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ChunkImageBuf','struct','Holds an owned framed chunk image.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::CodecId','struct','Names the stable identifier of a value''s token codec.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::CodecVersion','struct','Names the layout version of a value''s token codec.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::DecodeWork','struct','Names units of work a decode has spent: one per record, one per payload byte, and one per chunk-image byte verified on a seam.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::EditDepth','struct','Names the constructor depth of an edited node, zero at the value''s root.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::FlatBytes','struct','Holds the owned flat form of one value: its canonical token body, with no store and no seam.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::MAX_DECODE_WORK','constant','Names the most work one decode may spend, two to the thirty-fourth units.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ManifestImage','struct','Holds a value manifest image: the domain, then the manifest''s fields.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ManifestImageBuf','struct','Holds an owned value manifest image.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::SeamDepth','struct','Names how many chunk seams a reader is inside at once.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::TokenBody','struct','Holds a token body: a sequence of token records, as a chunk frames it and as the flat form carries it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::TokenBytes','struct','Holds an inline canonical byte payload.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('storage-values','units::ValueManifestVersion','struct','Names the layout version of a value manifest.',NULL,'fits','sound',NULL);
